CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, email TEXT NOT NULL UNIQUE, phone TEXT NOT NULL UNIQUE, pass_hash TEXT NOT NULL, pass_salt TEXT NOT NULL, name TEXT NOT NULL, instagram TEXT NOT NULL, handle TEXT NOT NULL UNIQUE, plan TEXT NOT NULL DEFAULT 'prata', plan_until INTEGER, trial_until INTEGER, ref_code TEXT UNIQUE, referred_by INTEGER, status TEXT NOT NULL DEFAULT 'ativo', is_admin INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, ip TEXT, ua TEXT); CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id); CREATE TABLE IF NOT EXISTS sms_codes (id TEXT PRIMARY KEY, phone TEXT NOT NULL, purpose TEXT NOT NULL, code_hash TEXT NOT NULL, payload TEXT, attempts INTEGER NOT NULL DEFAULT 0, used INTEGER NOT NULL DEFAULT 0, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS trial_registry (kind TEXT NOT NULL, value_hash TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY (kind, value_hash)); CREATE TABLE IF NOT EXISTS links (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title TEXT NOT NULL, url TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, clicks INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL); CREATE INDEX IF NOT EXISTS idx_links_user ON links(user_id, position); CREATE TABLE IF NOT EXISTS profiles (user_id INTEGER PRIMARY KEY, title TEXT, bio TEXT, theme TEXT NOT NULL DEFAULT 'noite', updated_at INTEGER NOT NULL); CREATE TABLE IF NOT EXISTS visits (user_id INTEGER NOT NULL, day TEXT NOT NULL, views INTEGER NOT NULL DEFAULT 0, PRIMARY KEY (user_id, day)); CREATE TABLE IF NOT EXISTS rate_limits (key TEXT PRIMARY KEY, window_start INTEGER NOT NULL, count INTEGER NOT NULL);
